var builder=WebApplication.CreateBuilder(args);var app=builder.Build();var produtos=new List<Produto>{new(1,"Teclado",99.9m),new(2,"Mouse",49.9m)};app.MapGet("/",()=>"API de Produtos .NET");app.MapGet("/produtos",()=>produtos);app.MapGet("/produtos/{id:int}",(int id)=>produtos.FirstOrDefault(x=>x.Id==id) is {} p?Results.Ok(p):Results.NotFound());app.MapPost("/produtos",(Produto p)=>{if(p.Preco<0||string.IsNullOrWhiteSpace(p.Nome))return Results.BadRequest();if(produtos.Any(x=>x.Id==p.Id))return Results.Conflict();produtos.Add(p);return Results.Created($"/produtos/{p.Id}",p);});app.MapDelete("/produtos/{id:int}",(int id)=>{var p=produtos.FirstOrDefault(x=>x.Id==id);if(p is null)return Results.NotFound();produtos.Remove(p);return Results.NoContent();});app.Run();record Produto(int Id,string Nome,decimal Preco);
